   393	std::vector<text_box> page::text_list(int opt_flag) const
   394	{
   395	    std::vector<text_box>  output_list;
   396	
   397	    /* config values are same with Qt5 Page::TextList() */
   398	    auto output_dev = std::make_unique<TextOutputDev>(
   399	        nullptr, /* char* fileName */
   400	        false,   /* bool physLayoutA */
   401	        0,       /* double fixedPitchA */
   402	        false,   /* bool rawOrderA */
   403	        false    /* bool append */
   404	    );
   405	
   406	    /*
   407	     * config values are same with Qt5 Page::TextList(),
   408	     * but rotation is fixed to zero.
   409	     * Few people use non-zero values.
   410	     */
   411	    d->doc->doc->displayPageSlice(output_dev.get(),
   412	                                  d->index + 1,           /* page */
   413	                                  72, 72, 0,              /* hDPI, vDPI, rot */
   414	                                  false, false, false,    /* useMediaBox, crop, printing */
   415	                                  -1, -1, -1, -1,         /* sliceX, sliceY, sliceW, sliceH */
   416	                                  nullptr, nullptr,       /* abortCheckCbk(), abortCheckCbkData */
   417	                                  nullptr, nullptr,       /* annotDisplayDecideCbk(), annotDisplayDecideCbkData */
   418	                                  true);                  /* copyXRef */
   419	
   420	    if (std::unique_ptr< TextWordList > word_list{output_dev->makeWordList()}) {
   421	
   422	        output_list.reserve(word_list->getLength());
   423	        for (int i = 0; i < word_list->getLength(); i ++) {
   424	            TextWord *word = word_list->get(i);
   425	
   426	            std::unique_ptr<GooString> gooWord{word->getText()};
   427	            ustring ustr = ustring::from_utf8(gooWord->c_str());
   428	
   429	            double xMin, yMin, xMax, yMax;
   430	            word->getBBox(&xMin, &yMin, &xMax, &yMax);
   431	
   432	            text_box tb{new text_box_data{
   433	                ustr,
   434	                {xMin, yMin, xMax-xMin, yMax-yMin},
   435	                word->getRotation(),
   436	                {},
   437	                word->hasSpaceAfter() == true,
   438	                nullptr
   439	            }};
   440	
   441	            std::unique_ptr<text_box_font_info_data> tb_font_info = nullptr;
   442	            if (opt_flag & page::text_list_include_font) {
   443	                d->init_font_info_cache();
   444	
   445	                std::unique_ptr<text_box_font_info_data> tb_font{new text_box_font_info_data{
   446	                    word->getFontSize(), // double font_size
   447	                    {},                  // std::vector<text_box::writing_mode> wmodes;
   448	                    d->font_info_cache,  // std::vector<font_info> font_info_cache;
   449	                    {}                   // std::vector<int> glyph_to_cache_index;
   450	                }};
   451	
   452	                tb_font_info = std::move(tb_font);
   453	            };
   454	
   455	            tb.m_data->char_bboxes.reserve(word->getLength());
   456	            for (int j = 0; j < word->getLength(); j ++) {
   457	                word->getCharBBox(j, &xMin, &yMin, &xMax, &yMax);
   458	                tb.m_data->char_bboxes.emplace_back(xMin, yMin, xMax-xMin, yMax-yMin);
   459	            }
   460	
   461	            if (tb_font_info && d->font_info_cache_initialized) {
   462	                tb_font_info->glyph_to_cache_index.reserve(word->getLength());
   463	                for (int j = 0; j < word->getLength(); j++) {
   464	                    const TextFontInfo* cur_text_font_info = word->getFontInfo(j);
   465	
   466	                    // filter-out the invalid WMode value here.
   467	                    switch (cur_text_font_info->getWMode()) {
   468	                    case 0:
   469	                        tb_font_info->wmodes.push_back(text_box::horizontal_wmode);
   470	                        break;
   471	                    case 1:
   472	                        tb_font_info->wmodes.push_back(text_box::vertical_wmode);
   473	                        break;
   474	                    default:
   475	                        tb_font_info->wmodes.push_back(text_box::invalid_wmode);
   476	                    };
   477	
   478	                    tb_font_info->glyph_to_cache_index[j] = -1;
   479	                    for (size_t k = 0; k < tb_font_info->font_info_cache.size(); k++) {
   480	                        if (cur_text_font_info->matches(&(tb_font_info->font_info_cache[k].d->ref))) {
   481	                            tb_font_info->glyph_to_cache_index[j] = k;
   482	                            break;
   483	                        }
   484	                    }
   485	                }
   486	                tb.m_data->text_box_font = std::move(tb_font_info);
   487	            }
   488	
   489	            output_list.push_back(std::move(tb));
   490	        }
   491	    }
   492	
   493	    return output_list;
   494	}
